use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let mut data: Vec<i64> = input.as_array().unwrap();
    let cents = data.remove(0);
    let n = data.remove(0) as usize;

    let mut shares: Vec<i64> = vec![0; n];
    let mut remaining = cents;

    for i in 0..n {
        let share = remaining / (n - i);
        let remainder = remaining % (n - i);
        shares[i] = share;
        remaining -= share;
        if remainder == 0 {
            break;
        }
    }

    for i in (0..n).rev() {
        if shares[i] - shares[i - 1] > 1 {
            shares[i] -= 1;
            shares[i - 1] += 1;
            remaining += 1;
        }
    }

    let mut result: Vec<i64> = vec![0; n];
    result[0] = shares[0];
    for i in 1..n {
        result[i] = result[i - 1] + shares[i];
    }

    Value::from(result)
}
```

This code takes in a JSON array with two elements: the first being the total cents and the second being the number of shares. It then calculates the shares such that the largest share is as close as possible to the total cents divided by the number of shares. If there is a remainder, it distributes it among the smaller shares starting from the smallest. The function returns a JSON array with the calculated shares.
